planningClickActionMessage: "The Gantt view now offers two distinct operating modes. <ul> <li>The “display of details on a single click” mode&#44 which is the historical mode of ProjeQtOr.<br/> In this mode&#44 simply clicking on a row in the table allows you to show its detail.</li> <li>The &#34display on double click&#34 mode&#44 which is a new mode introduced in V11.0.<br/> In this mode&#44 simply clicking on a line puts the line into edit mode.<br/> You must double-click on the line to display the detail.<br/> <b>This is the new default mode</b>.</li> </ul> If you want to return to the old operating mode&#44 change the setting in the dedicated pop-up via the icon <img src='../view/img/iconThreePoints.png' style='width&#58 30px;top&#58 7px;position&#58 relative;'/>.<br/> You can also just right-click on the line for the context menu.",
