startGuideActivity: "Atividades são as tarefas planeadas nos seus projetos. <br/>Você pode criar a estrutura de trabalho dos seus projetos. <br/>Não existe limite nos número de níveis desta estrutura em fases/sub-fases/tarefas/sub-tarefas...",
startGuideAffectation: "Um recurso tem de estar afeto a um projeto para poder ver os seus itens.<br/>A afetação a um projeto dá automaticamente visibilidade aos itens dos seus sub-projetos.",
startGuideClient: "Clientes são as entidades para quem você está a trabalhar.<br/>Podem ser internas ou externas à sua organização.",
startGuideContact: "Contatos são as pessoas que contata dentro das entidades dos seus clientes.",
startGuideFooter: "Estas são as principais funcionalidades.<br/>Uma vez que se familiarize com estas funções você será capaz de descobrir os outros (numerosos) módulos capazes de cobrir as necessidades da gestão dos seus projetos.",
startGuideImputation: "Os recursos introduzem o seu trabalho real no Ecran de introdução de trabalho real dia a dia e atividade a atividade.<br/>Re-estimtativa do «restante» trabalho permite a atualização do planeamento do projeto com o progresso real.",
startGuideIntro: "Aqui está uma curta ajuda para facilitar os seus primeiros passos com o ProjeQtOr.<br>Siga estas intstruções para configurar os primeiros elementos.<br>Não hesite em pressionar [F1] para aceder ao manual do utilizador onde encontrará mais ajuda.<br>Volte para a págine &#34;Hoje&#34; para encontrar esta página de &#34;guia inicial&#34;.",
startGuideMilestone: "Marcos são as datas chave dos projetos.<br/>Podem definir entregas (marcos com data fixa) ou entregáveis (marcos com data flexível).",
startGuidePlanning: "O Planeamento propõe uma vista Gantt.<br/>Para planear atividades você tem de atribuir recursos a atividades e definir trabalho para ser feito porque o planeamento gira em torno do trabalho.<br/>Depois você pode definir relações entre tarefas (ligações a precedentes) e marcos...<br/>Você pode depois correr um cálculo do planeamento tendo em conta todas as restrições dos recursos como por exemplo a disponibildiade dos mesmos.",
startGuideProject: "Projecto é o item principal no ProjeQtOr.<br/>Todos os itens estão ligados a um projeto.<br/>Direitos de acesso são também definidos ao nível de projeto.",
startGuideResource: "Recursos são as pessoas que irão trabalhar nas tarefas.<br/>Se ativar a opção « é um utilizador » o recurso poderá ligar-se ao ProjeQtOr.",
startGuideTicket: "Os tickets permitem-lhe seguir todos os eventos pontuais ligados a um projeto como os bugs ou qualquer tipo de pedido<br/>Eles podem facilmente ser copiados para atividades sempre que necesário sem que  seja necessário reintroduzir dados e mantêm uma ligaçãoo ao pedido original.",
startGuideTitle: "Guia de Início",
startGuideUser: "Utilizadores são as pessoas que podem-se ligar à aplicação.<br/>Eles têm de ter um perfil que irá determinar os seus direitos de acesso a cada elemento.",
